def get_port(url):
    parsed = urlparse(url)
    if parsed.port:
        return parsed.port
    elif parsed.scheme == "https":
        return 443
    else:
        return 80

def get_ip(url):
    parsed = urlparse(url)
    return parsed.netloc

async def send_http_request(session, url, req_num, timeout=3):
    port = get_port(url)
    headers = {
        'User-Agent': random.choice(user_agents),
        'Accept': '*/*',
        'Connection': 'keep-alive'
    }
    try:
        async with session.get(url, headers=headers, timeout=timeout) as resp:
            return f"Request {req_num} | URL {url} | Port {port} | Status {resp.status}"
    except Exception as e:
        return f"Request {req_num} | URL {url} | Port {port} | Error: {e}"

async def send_udp_request(ip, port, payload, req_num, timeout=1):
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        sock.sendto(payload.encode(), (ip, int(port)))
        return f"Request {req_num} | IP {ip} | Port {port} | Sent"
    except Exception as e:
        return f"Request {req_num} | IP {ip} | Port {port} | Error: {e}"
    finally:
        sock.close()

